public class VolumeCalculator {
    private List<SolidShape> solidShapes;

    public VolumeCalculator(List<SolidShape> solidShapes) {
        this.solidShapes = solidShapes;
    }

    public double sumVolumes() {
        double totalVolume = 0;
        for (SolidShape solidShape : solidShapes) {
            totalVolume += solidShape.volume();
        }
        return totalVolume;
    }
}

